"use strict";

/* eslint-env browser */
(function () {
  'use strict';

  document.addEventListener('DOMContentLoaded', function () {
    var desktopParent = document.querySelector('#desktop-darkmode-parent');
    var mobileParent = document.querySelector('#mobile-darkmode-parent');
    var darkmodeComponent = document.querySelector('#darkmode-component');

    function moveDarkmode() {
      if (window.innerWidth < 1024) {
        if (!mobileParent.contains(darkmodeComponent)) {
          mobileParent.appendChild(darkmodeComponent);
        }
      } else {
        if (!desktopParent.contains(darkmodeComponent)) {
          desktopParent.appendChild(darkmodeComponent);
        }
      }
    }

    moveDarkmode();
    window.addEventListener('resize', moveDarkmode);
  });
})();

function handleDarkMode() {
  return {
    theme: "light",
    toggleTheme: function toggleTheme(theme) {
      this.theme = theme;
      this.setCookie("theme", theme, 30);
      this.applyTheme();
    },
    applyTheme: function applyTheme() {
      var html = document.documentElement;

      if (this.theme === "dark") {
        html.classList.add("dark");
      } else {
        html.classList.remove("dark");
      }
    },
    setCookie: function setCookie(name, value, days) {
      var expires = new Date(Date.now() + days * 864e5).toUTCString();
      document.cookie = "".concat(name, "=").concat(value, "; expires=").concat(expires, "; path=/");
    },
    getCookie: function getCookie(name) {
      return document.cookie.split("; ").reduce(function (r, v) {
        var parts = v.split("=");
        return parts[0] === name ? decodeURIComponent(parts[1]) : r;
      }, "");
    },
    init: function init() {
      var savedTheme = this.getCookie("theme");

      if (savedTheme) {
        this.theme = savedTheme;
      } else {
        this.theme = window.matchMedia("(prefers-color-scheme: dark)").matches ? "dark" : "light";
      }

      this.applyTheme();
    }
  };
}

function handleMenu() {
  return {
    smMenuVisible: false,
    activeParent: "",
    isScrolled: false,
    isSearchOpen: false,
    searchList: [1, 2, 3, 4],
    searching: false,
    searchInput: "",
    toggleSmMenu: function toggleSmMenu() {
      if (this.smMenuVisible) {
        this.smMenuVisible = false;
        this.activeParent = "";
      } else {
        this.smMenuVisible = true;
      }
    },
    openParentSm: function openParentSm(target) {
      if (window.innerWidth < 1024) {
        if (this.activeParent === target) {
          this.activeParent = "";
        } else {
          this.activeParent = target;
        }
      }
    },
    openParentLg: function openParentLg(target) {
      if (window.innerWidth >= 1024) {
        this.activeParent = target;
      }
    },
    closeParentLg: function closeParentLg() {
      if (window.innerWidth >= 1024) {
        this.activeParent = "";
      }
    },
    checkScroll: function checkScroll() {
      var y = window.scrollY;

      if (!this.isScrolled && y > 210) {
        this.isScrolled = true;
      } else if (this.isScrolled && y < 150) {
        this.isScrolled = false;
      }
    },
    openSearch: function openSearch() {
      this.isSearchOpen = true;
      fixBody();
    },
    closeSearch: function closeSearch() {
      this.isSearchOpen = false;
      unfixBody();
    },
    closeDesktopSearch: function closeDesktopSearch() {
      if (window.innerWidth >= 1024) {
        if (this.isSearchOpen) {
          this.closeSearch();
        }
      }
    },
    init: function init() {
      var _this = this;

      this.checkScroll();
      window.addEventListener("scroll", function () {
        _this.checkScroll();
      });
    }
  };
}